use std::sync::OnceLock;
use tokio::runtime::Runtime;

struct Worker {
    runtime: OnceLock<Runtime>,
}

impl Worker {
    fn new() -> Self {
        Self {
            runtime: OnceLock::new(),
        }
    }

    fn get_runtime(&self) -> &Runtime {
        self.runtime.get_or_init(|| {
            // Panics if called from within a Tokio task!
            Runtime::new().expect("failed to create runtime")
        })
    }
}

// Caller (inside a Tokio task):
async fn process() {
    let worker = Worker::new();
    let rt = worker.get_runtime(); // panic: Cannot start a runtime from within a runtime
    rt.block_on(some_future());
}

good_example:
use tokio::sync::OnceCell;
use tokio::runtime::Runtime;

struct Worker {
    runtime: OnceCell<Runtime>,
}

impl Worker {
    fn new() -> Self {
        Self {
            runtime: OnceCell::new(),
        }
    }

    async fn get_runtime(&self) -> &Runtime {
        self.runtime
            .get_or_init(|| async {
                // If we truly need a dedicated runtime, we must NOT
                // be inside a Tokio task here. Instead, accept a
                // pre-built Runtime or use tokio::task::spawn_blocking
                // to construct it off the async executor.
                Runtime::new().expect("failed to create runtime")
            })
            .await
    }
}

// Caller (inside a Tokio task):
async fn process() {
    let worker = Worker::new();
    let rt = worker.get_runtime().await; // safe: no nested runtime creation
    // Use spawn_blocking or channel to interact with the dedicated runtime
    tokio::task::spawn_blocking(move || {
        rt.block_on(some_future());
    })
    .await
    .unwrap();
}
